-- Performance, By case: group objectives by the SESSION they belong to (from the
-- learning-objective spreadsheets), not by the question bank they were answered in.
-- Run this first, then migration_case_sessions.sql (generated by tools/case_map.py
-- --sessions-out). No student data is touched.

alter table public.case_objectives add column if not exists session_title text;

-- replaces the by-bank view from migration_020 (unused once the page is updated)
drop view if exists public.v_perf_case_bank_objective;

-- One row per case / session / objective the student has answered at least once.
-- Objectives with no session recorded fall under 'Other objectives'.
create or replace view public.v_perf_case_session_objective as
  select c.number as case_number,
         coalesce(co.session_title, 'Other objectives') as session,
         t.name as topic,
         t.description,
         count(*) as answered,
         count(*) filter (where m.is_correct) as correct,
         round(100.0 * count(*) filter (where m.is_correct) / nullif(count(*), 0), 1) as pct,
         count(*) filter (where m.is_latest) as latest_answered,
         count(*) filter (where m.is_latest and m.is_correct) as latest_correct,
         round(100.0 * count(*) filter (where m.is_latest and m.is_correct)
               / nullif(count(*) filter (where m.is_latest), 0), 1) as latest_pct
    from v_my_answers m
    join topics t on t.id = m.topic_id
    join case_objectives co on 'Objective ' || co.code = t.name
    join cases c on c.number = co.case_number
   group by c.number, co.session_title, t.name, t.description;

grant select on public.v_perf_case_session_objective to authenticated;
